def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = 4

    row_seps = [r for r in range(h) if all(v == divider for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    def segments(size, seps):
        result, start = [], 0
        for s in seps:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < size:
            result.append((start, size))
        return result

    rows = segments(h, row_seps)
    cols = segments(w, col_seps)

    # Use the tile containing the most non-background cells as the repeating tile.
    background = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    best = None
    best_score = -1
    for r0, r1 in rows:
        for c0, c1 in cols:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(v != background for row in tile for v in row)
            if score > best_score:
                best_score, best = score, tile

    out = [row[:] for row in grid]
    if best is not None:
        for r0, r1 in rows:
            for c0, c1 in cols:
                for dr in range(r1 - r0):
                    for dc in range(c1 - c0):
                        out[r0 + dr][c0 + dc] = best[dr][dc]
    return out
